                }

            });
        }
        return btnReplace;
    }

    /**
     * This method initializes the delete button for a banner.
     *
     * @Return javax.swing.JButton - the delete button for.
     */
    private JButton getBtnDelete() {
        if (null == btnDelete) {
            btnDelete = new JButton();
            btnDelete.setBounds(305, 5, 140, 40);
