                    Integer.valueOf(listResult.get(b.getRating() - 1).intValue() + 1));
                }
            }
        } catch (SQLException e) {
            throw new RemoteException(ErrorMessage.ERROR_DBMS);
        } catch (Exception e) {
            throw new RemoteException(ErrorMessage.ERROR_UNKNOWN);
